/* eslint-disable react/jsx-no-undef */

"use client";
import { useEffect, useState } from "react";
import Link from "next/link";
import DuoTranslate from "../DuoMCB/DuoTranslate";

const SectionHeader = ({ icon, title }) => (
  <div style={{ display: "flex", alignItems: "center", gap: 12, fontSize: 22, fontWeight: 700, color: "#0B4F5C", marginBottom: 20, paddingBottom: 12, borderBottom: "2px solid #f0f0f0" }}>
    <span>{icon}</span><span>{title}</span>
  </div>
);

export default function Lesson7_HamSoBacHai() {
  const [lang, setLang] = useState("vi");
  const [revealedAnswers, setRevealedAnswers] = useState({});
  const [gameMode, setGameMode] = useState("mc");

  const [mcIndex, setMcIndex] = useState(0);
  const [mcSelected, setMcSelected] = useState(null);
  const [mcScore, setMcScore] = useState(0);
  const [mcDone, setMcDone] = useState(false);
  const [mcHistory, setMcHistory] = useState([]);

  useEffect(() => {
    if (typeof window === "undefined") return;
    const els = document.querySelectorAll("[data-reveal]");
    const obs = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add("visible");
        }
      });
    }, { threshold: 0.1 });
    els.forEach((el) => obs.observe(el));
    return () => obs.disconnect();
  }, []);

  const t = (vi, en) => (lang === "vi" ? vi : en);
  const toggleAnswer = (id) => setRevealedAnswers((p) => ({ ...p, [id]: !p[id] }));

  const mcQuestions = [
    {
      q: t("Hàm số nào sau đây là hàm số bậc hai?", "Which of the following is a quadratic function?"),
      options: ["y = 2x + 1", "y = x² - 4x + 3", "y = x³ + x", "y = 1/x²"],
      answer: 1,
      explain: t("Hàm số bậc hai có dạng y = ax² + bx + c (a ≠ 0).", "A quadratic function has the form y = ax² + bx + c (a ≠ 0).")
    },
    {
      q: t("Tọa độ đỉnh I của Parabol y = x² - 2x + 3 là?", "What are the coordinates of the vertex I of the parabola y = x² - 2x + 3?"),
      options: ["(1, 2)", "(2, 3)", "(-1, 6)", "(0, 3)"],
      answer: 0,
      explain: t("x = -b/2a = 2/2 = 1. Thay vào y = 1² - 2(1) + 3 = 2.", "x = -b/2a = 1. Substitute to get y = 2.")
    }
  ];

  const handleMcSelect = (i) => { if (mcSelected !== null) return; setMcSelected(i); const correct = i === mcQuestions[mcIndex].answer; if (correct) setMcScore(s => s + 1); setMcHistory(h => [...h, { q: mcIndex, selected: i, correct }]); };
  const handleMcNext = () => { if (mcIndex + 1 >= mcQuestions.length) setMcDone(true); else { setMcIndex(i => i + 1); setMcSelected(null); } };

  return (
    <div style={{ width: "100%", background: "#ffffff", display: "flex", justifyContent: "center" }}>
      <div style={{ width: "1200px", maxWidth: "95%", color: "black", paddingTop: 60, paddingBottom: 80 }}>
        
        <header className="reveal" data-reveal style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 40 }}>
          <div>
            <div style={{ fontWeight: "bold", fontSize: 22, color: "#0B4F5C" }}>{t("Chương III · Hàm Số và Đồ Thị", "Chapter III · Functions and Graphs")}</div>
            <div style={{ fontSize: 28, fontWeight: 600 }}>{t("Bài 2: Hàm số bậc hai", "Lesson 2: Quadratic Functions")}</div>
          </div>
          <div style={{ display: "flex", gap: 10 }}>
            <button onClick={() => setLang("vi")} style={{ background: lang === "vi" ? "black" : "#eee", color: lang === "vi" ? "white" : "black", border: "none", padding: "10px 20px", borderRadius: 8, cursor: "pointer" }}>VN</button>
            <button onClick={() => setLang("en")} style={{ background: lang === "en" ? "black" : "#eee", color: lang === "en" ? "white" : "black", border: "none", padding: "10px 20px", borderRadius: 8, cursor: "pointer" }}>EN</button>
          </div>
        </header>

        <section id="lyThuyet" style={{ marginBottom: 60 }}>
          <SectionHeader icon="📖" title={t("1. Định nghĩa & Đồ thị", "1. Definition & Graph")} />
          <div style={{ padding: 25, background: "#f9f9f9", borderRadius: 15, marginBottom: 20 }}>
            <p>
              <strong>{t("Dạng tổng quát:", "General Form:")}</strong>{" "}
              y = ax² + bx + c (a ≠ 0)
            </p>
            <p>{t("Đồ thị là một đường Parabol (P) có:", "The graph is a Parabola (P) with:")}</p>
            <ul style={{ paddingLeft: 20 }}>
              <li>
                {t("Đỉnh:", "Vertex:")} I(-b/(2a); -Δ/(4a))
              </li>
              <li>
                {t("Trục đối xứng:", "Axis of symmetry:")} x = -b/(2a)
              </li>
              <li>{t("Bề lõm:", "Concavity:")} {t("Quay lên nếu a > 0, quay xuống nếu a < 0.", "Upward if a > 0, downward if a < 0.")}</li>
            </ul>
          </div>
        </section>

        <section id="miniGame" style={{ marginBottom: 60 }}>
          <SectionHeader icon="🎮" title={t("Mini Game Kiểm Tra", "Knowledge Check")} />
          <div style={{ display: "flex", gap: 10, marginBottom: 20 }}>
            {["mc", "tf", "fill"].map(mode => (
              <button key={mode} onClick={() => setGameMode(mode)} style={{ padding: "10px 20px", borderRadius: 8, background: gameMode === mode ? "black" : "#eee", color: gameMode === mode ? "white" : "black", border: "none", cursor: "pointer" }}>
                {mode.toUpperCase()}
              </button>
            ))}
          </div>

          <div style={{ padding: 30, background: "#f9f9f9", borderRadius: 15, boxShadow: "0 4px 12px rgba(0,0,0,0.05)" }}>
            {gameMode === "mc" && !mcDone && (
              <div>
                <p style={{ fontSize: 18, fontWeight: 600 }}>{mcQuestions[mcIndex].q}</p>
                <div style={{ display: "flex", flexDirection: "column", gap: 10, marginTop: 20 }}>
                  {mcQuestions[mcIndex].options.map((opt, i) => (
                    <button key={i} onClick={() => handleMcSelect(i)} style={{ padding: 15, textAlign: "left", borderRadius: 10, border: "1px solid #ddd", background: mcSelected === i ? "#eee" : "white", cursor: "pointer" }}>
                      {opt}
                    </button>
                  ))}
                </div>
                {mcSelected !== null && <button onClick={handleMcNext} style={{ marginTop: 20, padding: "10px 20px", background: "black", color: "white", border: "none", borderRadius: 8 }}>{t("Tiếp theo", "Next")}</button>}
              </div>
            )}
            {gameMode === "mc" && mcDone && <ResultSummary items={mcHistory} onReset={() => {setMcIndex(0); setMcDone(false); setMcSelected(null); setMcHistory([]);}} />}
            
            {/* Logic for TF and Fill follows the same pattern as your sample */}
            {gameMode === "tf" && (
            <div style={{ padding: 24, borderRadius: 10, background: "#f9f9f9", boxShadow: "0 4px 12px rgba(0,0,0,0.1)" }}>
              {!tfDone ? (
                <>
                  <div style={{ color: "#777", fontSize: 15, marginBottom: 14 }}>{t("Thẻ", "Card")} {tfIndex + 1}/{tfCards.length} · {t("Điểm:", "Score:")} {tfScore}</div>
                  <article style={{ background: "white", borderRadius: 10, padding: 24, marginBottom: 20, textAlign: "center", boxShadow: "0 4px 12px rgba(0,0,0,0.1)" }}>
                    <div style={{ fontSize: 18, lineHeight: 1.7, marginBottom: 24 }}>{tfCards[tfIndex].stmt}</div>
                    {!tfFlipped ? (
                      <div style={{ display: "flex", gap: 16, justifyContent: "center" }}>
                        <button onClick={() => handleTfAnswer(true)} style={{ padding: "12px 36px", background: "#eafaf1", color: "#1e8449", border: "2px solid #1e8449", borderRadius: 8, fontWeight: 700, fontSize: 16, cursor: "pointer" }}>✅ {t("ĐÚNG", "TRUE")}</button>
                        <button onClick={() => handleTfAnswer(false)} style={{ padding: "12px 36px", background: "#fdf2f2", color: "#922b21", border: "2px solid #922b21", borderRadius: 8, fontWeight: 700, fontSize: 16, cursor: "pointer" }}>❌ {t("SAI", "FALSE")}</button>
                      </div>
                    ) : (
                      <><div style={{ padding: "12px 16px", background: "#f9f9f9", borderRadius: 8, fontSize: 15, color: "#555", textAlign: "left", marginBottom: 14, boxShadow: "0 4px 12px rgba(0,0,0,0.1)" }}>💬 {tfCards[tfIndex].explain}</div><button onClick={handleTfNext} style={{ padding: "12px 28px", background: "black", color: "white", border: "none", borderRadius: 8, fontWeight: 600, fontSize: 15, cursor: "pointer" }}>{tfIndex + 1 < tfCards.length ? t("Thẻ tiếp ▶", "Next ▶") : t("Xem kết quả", "See Results")}</button></>
                    )}
                  </article>
                </>
              ) : (
                <ResultSummary items={tfResultItems} onReset={resetTf} scoreLabel={tfScore === tfCards.length ? t("Xuất sắc! 🎉", "Perfect! 🎉") : t("Cố gắng thêm! 💪", "Keep going! 💪")} />
              )}
            </div>
          )}
           {gameMode === "fill" && (
            <div style={{ padding: 24, borderRadius: 10, background: "#f9f9f9", boxShadow: "0 4px 12px rgba(0,0,0,0.1)" }}>
              {!fillChecked ? (
                <>
                  <div style={{ fontSize: 18, fontWeight: 600, marginBottom: 20 }}>{t("Điền câu trả lời vào chỗ trống", "Fill in each blank")}</div>
                  {fillQuestions.map((q, qi) => (
                    <div key={q.id} style={{ marginBottom: 24 }}>
                      <div style={{ fontSize: 15, color: "#777", marginBottom: 6 }}>{t("Câu", "Q")} {qi + 1}</div>
                      <div style={{ fontSize: 16, lineHeight: 1.7, marginBottom: 10 }}>{q.template}</div>
                      <input value={fillAnswers[q.id] || ""} onChange={(e) => setFillAnswers((p) => ({ ...p, [q.id]: e.target.value }))} placeholder={t("Nhập đáp án...", "Enter answer...")} style={{ width: "100%", padding: "12px 16px", borderRadius: 8, fontSize: 15, outline: "none", border: "1px solid #ddd", background: "white", boxShadow: "0 4px 12px rgba(0,0,0,0.1)", boxSizing: "border-box" }} />
                    </div>
                  ))}
                  <button onClick={() => setFillChecked(true)} style={{ padding: "12px 32px", background: "black", color: "white", border: "none", borderRadius: 8, fontWeight: 600, fontSize: 15, cursor: "pointer" }}>{t("Kiểm tra", "Check Answers")}</button>
                </>
              ) : (
                <ResultSummary items={fillResultItems} onReset={() => { setFillAnswers({}); setFillChecked(false); }} scoreLabel={fillScore === fillQuestions.length ? t("Xuất sắc! 🎉", "Perfect! 🎉") : fillScore >= 2 ? t("Tốt lắm! 👍", "Well done! 👍") : t("Cố gắng thêm! 💪", "Keep going! 💪")} />
              )}
            </div>
          )}
          </div>
        </section>
        <DuoTranslate />
        <style>{`.reveal { opacity:0; transform:translateY(20px); transition: all 0.5s; } .reveal.visible { opacity:1; transform:translateY(0); }`}</style>
      </div>
    </div>
  );
}